/*
 * aien-universe.js: /aien/ as the iMac shows Aien. Generated by
 * om/aien-universe/universe.om (Omega) with the shared contract of
 * om/allen-page/contract.om; do not edit.
 *
 * The page is the sky. The native scene (allen-scene.js, aienux da55660
 * compiled to WebAssembly) plays the two black holes merging into Aien in
 * the middle, with the native chirp (allen-audio.js) on the first gesture.
 * Visitors type in one glass oval under him; on Enter the letters float up
 * into him. His reply is one bubble beside him that fades once it has been
 * read: the time grows with its length, and hover, focus or a tap hold it.
 * There is never more than one bubble, no transcript and no scrolling page.
 * Things that are not chat open as glass panes (allen-panes.js): programs
 * and cards from a reply, the speed test and the math engine.
 *
 * allen.js stays the transport and keeps writing every reply into the
 * screen reader log; this script only reads that log, moves cards into
 * panes and mirrors the newest reply into the bubble. Every string it shows
 * goes through textContent.
 */
(() => {
  'use strict';
  const byId = id => document.getElementById(id);
  const root = byId('allen');
  const sky = byId('aien-sky');
  if (!root || !sky) return;
  const log = byId('allen-log');
  const form = byId('allen-form');
  const input = byId('allen-input');
  const examples = byId('allen-examples');
  const bubble = byId('aien-bubble');
  const bubbleWho = byId('aien-bubble-who');
  const bubbleText = byId('aien-bubble-text');
  const bubbleActs = byId('aien-bubble-acts');
  const panesHost = byId('aien-panes');
  const menu = byId('aien-menu');
  const replayButton = byId('aien-replay');
  const soundButton = byId('aien-sound');
  const speedButton = byId('aien-speed');
  const mathButton = byId('aien-math');
  const speedTable = menu.querySelector('dl.allen-speed');
  const speedHome = speedTable.nextElementSibling;
  const MATH = '/aien/api/math';
  /* Reading time. 200 words a minute at 6 characters a word is 50 ms a
     character (WolframLanguageEvaluator: UnitConvert[Quantity[1, "Minutes"]/(200*6),
     "Milliseconds"] -> 50 ms), after a 2500 ms glance, at most 30 s. */
  const READ_BASE = 2500;
  const READ_CHAR = 50;
  const READ_MAX = 30000;
  const FADE_MS = 900;
  /* Panes this page opened that stay open at once; the oldest closes first. */
  const PANES_SHOWN = 3;
  /* The opening is the iMac's own order: the tube (native dusk, 4200 ms),
     then the two holes merge (native night: merger ends at 12300 ms) and
     become Aien (formed at 15300 ms). For the web the night's first 6800 ms
     (stars, lens, shadows) play 6.8 times faster, 1000 ms, then the spiral,
     merger and forming run at the native rate. With sound on the night runs
     at the native rate throughout, so the chirp stays on the merger.
     WolframLanguageEvaluator: {6800/1000, 4200 + 1000 + (15300 - 6800)} -> {34/5, 13700} ms. */
  const TUBE_MS = 4200;
  const WARP_END = 6800;
  const WARP_RATE = 6.8;
  const FORMED_MS = 15300;
  let scene = null;
  let formed = false;
  let stage = 'none';
  let warpFrom = 0;
  let watching = 0;
  let fallback = 0;
  const still = matchMedia('(prefers-reduced-motion: reduce)');
  function formUp() {
    if (formed) return;
    formed = true;
    stage = 'formed';
    clearTimeout(fallback);
    root.dataset.formed = 'yes';
    mirror();
  }
  function sceneTime() {
    const at = Number(sky.dataset.sceneTime);
    return Number.isFinite(at) && at >= 0 ? at : 0;
  }
  function sceneCall(name, arg) {
    if (!scene) return;
    try {
      scene[name](arg);
    } catch (_) {
      /* The sky is decoration; the conversation never depends on it. */
    }
  }
  /* The night: the two holes. Warped while no sound is armed. */
  function night() {
    sceneCall('enter', 'birth');
    root.dataset.opening = 'night';
    if (armed) {
      stage = 'night';
      if (audio) audio.resume();
    } else {
      stage = 'warp';
      warpFrom = performance.now();
    }
    clearTimeout(fallback);
    fallback = setTimeout(formUp, FORMED_MS + 1500);
  }
  /* Hand the clock back to the native loop at the native rate. */
  function unwarp(at) {
    stage = 'night';
    sceneCall('frame', at);
    sceneCall('mode', root.dataset.busy === 'true' ? 'thinking' : 'idle');
  }
  function watch(now) {
    watching = 0;
    if (!scene || stage === 'formed' || stage === 'none') return;
    if (stage === 'tube' && sceneTime() >= TUBE_MS) night();
    else if (stage === 'warp') {
      const at = (now - warpFrom) * WARP_RATE;
      if (at >= WARP_END) unwarp(WARP_END);
      else sceneCall('frame', at);
    }
    if (stage !== 'night' && stage !== 'formed') watching = requestAnimationFrame(watch);
  }
  function opening() {
    formed = false;
    root.dataset.formed = 'no';
    root.dataset.opening = 'tube';
    stage = 'tube';
    clearTimeout(fallback);
    fallback = setTimeout(formUp, TUBE_MS + FORMED_MS + 3000);
    if (!watching) watching = requestAnimationFrame(watch);
  }
  function startScene() {
    if (!window.AllenScene) {
      root.dataset.sky = 'off';
      formUp();
      return;
    }
    try {
      scene = window.AllenScene.mount(sky, { opening: still.matches ? 'idle' : 'dusk', interactive: false });
    } catch (_) {
      scene = null;
      root.dataset.sky = 'off';
      formUp();
      return;
    }
    if (scene.ready && typeof scene.ready.then === 'function') {
      scene.ready.then(() => {
        root.dataset.sky = 'on';
      }, () => {
        root.dataset.sky = 'off';
        formUp();
      });
    }
    sky.addEventListener('allen-scene-complete', event => {
      if (event.detail && event.detail.kind === 'birth') formUp();
    });
    sky.addEventListener('allen-scene-error', () => {
      root.dataset.sky = 'off';
      formUp();
    });
    if (still.matches) formUp();
    else opening();
  }
  const audio = window.AllenAudio || null;
  let armed = false;
  /* Browsers start sound only inside a gesture. The first click or key on
     the page arms the native chirp: during the tube it waits, paused, for
     the night to begin; during the night it joins where the scene is, and a
     warped night drops to the native rate so the chirp lands on the merger. */
  function firstGesture() {
    if (armed || !audio || audio.muted()) return;
    armed = true;
    try {
      if (stage === 'tube') {
        audio.enter({ kind: 'night', nightMs: 0 });
        audio.pause();
      } else if (stage === 'warp') {
        const at = Math.min(WARP_END, (performance.now() - warpFrom) * WARP_RATE);
        unwarp(at);
        audio.enter({ kind: 'night', nightMs: at });
      } else if (stage === 'night') {
        audio.enter({ kind: 'night', nightMs: sceneTime() });
      }
    } catch (_) {}
  }
  function showSound() {
    const on = !(audio && audio.muted());
    soundButton.textContent = on ? 'Sound: on' : 'Sound: off';
    soundButton.setAttribute('aria-pressed', on ? 'true' : 'false');
    soundButton.hidden = !audio;
  }
  /* Replay plays the whole opening again, tube first, with the sound armed
     by this click. */
  function replay() {
    menu.open = false;
    hideBubble(true);
    if (!scene || still.matches) return;
    if (audio) audio.stop();
    armed = false;
    sceneCall('enter', 'dusk');
    opening();
    firstGesture();
  }
  /* One bubble, never a scroll: a long reply turns pages inside the same
     bubble, each held for its own reading time. */
  const PAGE_CHARS = 180;
  let watched = null;
  let fadeTimer = 0;
  let goneTimer = 0;
  let pending = 0;
  let held = false;
  let fullText = '';
  let pageAt = 0;
  let armedFor = '';
  /* The message whose bubble was let go; it does not come back. */
  let dismissed = null;
  function clearTimers() {
    clearTimeout(fadeTimer);
    clearTimeout(goneTimer);
    fadeTimer = 0;
    goneTimer = 0;
    armedFor = '';
  }
  function hideBubble(now) {
    dismissed = watched;
    clearTimers();
    if (bubble.hidden) return;
    if (now) {
      bubble.hidden = true;
      bubble.dataset.state = 'gone';
      return;
    }
    bubble.dataset.state = 'fading';
    goneTimer = setTimeout(() => {
      bubble.hidden = true;
      bubble.dataset.state = 'gone';
    }, FADE_MS);
  }
  function readMs(text) {
    return Math.min(READ_MAX, READ_BASE + READ_CHAR * text.length);
  }
  function pagesOf(text) {
    const pages = [];
    let rest = text.trim();
    while (rest.length > PAGE_CHARS) {
      let cut = rest.lastIndexOf(' ', PAGE_CHARS);
      const para = rest.lastIndexOf('\n', PAGE_CHARS);
      if (para > PAGE_CHARS / 3) cut = para;
      else if (cut < PAGE_CHARS / 3) cut = PAGE_CHARS;
      pages.push(rest.slice(0, cut).trim());
      rest = rest.slice(cut).trim();
    }
    if (rest) pages.push(rest);
    return pages;
  }
  function paint() {
    const pages = pagesOf(fullText);
    if (pageAt > pages.length - 1) pageAt = Math.max(0, pages.length - 1);
    const page = pages[pageAt] || '';
    const last = pageAt >= pages.length - 1;
    if (bubbleText.textContent !== page) bubbleText.textContent = page;
    bubble.dataset.more = last ? 'no' : 'yes';
    bubbleActs.hidden = !last;
    return { page, last };
  }
  /* A finished page turns after its reading time; the last page fades once
     the reply is complete, unless it asks a question with buttons. */
  function schedule() {
    if (bubble.hidden || bubble.dataset.state === 'fading') return;
    const { page, last } = paint();
    if (held) {
      clearTimers();
      return;
    }
    let plan = '';
    if (!last) plan = `turn ${pageAt}`;
    else if (root.dataset.busy !== 'true' && !bubbleActs.querySelector('button:not([disabled])')) plan = `fade ${pageAt} ${page.length}`;
    if (plan === armedFor) return;
    clearTimers();
    armedFor = plan;
    if (!plan) return;
    fadeTimer = setTimeout(() => {
      armedFor = '';
      fadeTimer = 0;
      if (!plan.startsWith('turn')) {
        hideBubble(false);
        return;
      }
      pageAt += 1;
      if (!still.matches && bubbleText.animate) bubbleText.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 220, easing: 'ease-out' });
      schedule();
    }, readMs(page));
  }
  function showBubble(who, text) {
    fullText = text;
    if (bubbleWho.textContent !== who) bubbleWho.textContent = who;
    if (bubble.hidden || bubble.dataset.state === 'fading') {
      clearTimers();
      bubble.hidden = false;
    }
    bubble.dataset.state = 'shown';
    schedule();
  }
  function bodyText(body) {
    const parts = [];
    for (const child of body.children) {
      if (!child.matches('p.allen-p, p.allen-h, p.allen-err, p.allen-note')) continue;
      const text = child.textContent.trim();
      if (text) parts.push(text);
    }
    return parts.join('\n');
  }
  /* The newest message from Aien or Drake becomes the bubble. Cards and code
     move into panes as they appear, so allen.js keeps streaming into them;
     choice buttons move into the bubble so they stay clickable. */
  function adopt(item, body) {
    for (const child of [...body.children]) {
      if (child.matches('.allen-choices')) {
        bubbleActs.append(child);
      } else if (child.matches('.allen-code, .allen-card, .allen-consent, .allen-out, .allen-frame-box')) {
        paneFor(child, item);
      }
    }
  }
  function mirror() {
    pending = 0;
    const items = log.querySelectorAll('li.allen-msg-allen, li.allen-msg-drake');
    const item = items.length ? items[items.length - 1] : null;
    if (!item) return;
    const body = item.querySelector('.allen-body');
    if (!body) return;
    if (item !== watched) {
      watched = item;
      bubbleActs.replaceChildren();
      fullText = '';
      pageAt = 0;
      clearTimers();
    }
    adopt(item, body);
    if (item === dismissed) return;
    if (!formed) return;
    const text = bodyText(body);
    const who = item.classList.contains('allen-msg-drake') ? 'Drake' : 'Aien';
    if (text || bubbleActs.childElementCount) showBubble(who, text);
  }
  function soon() {
    if (!pending) pending = requestAnimationFrame(mirror);
  }
  let panes = null;
  const mine = [];
  let serial = 0;
  function freshId(stem) {
    serial += 1;
    return `${stem}${Date.now().toString(36)}${serial}`;
  }
  function keep(entry) {
    mine.push(entry);
    while (mine.length > PANES_SHOWN) {
      const old = mine.shift();
      try {
        old.close();
      } catch (_) {}
    }
  }
  function forget(id) {
    const at = mine.findIndex(entry => entry.id === id);
    if (at >= 0) mine.splice(at, 1);
    if (id === speedId) {
      speedId = '';
      speedHome.before(speedTable);
    }
  }
  function startPanes() {
    if (!window.AllenPanes) return;
    try {
      panes = window.AllenPanes.mount(panesHost, { onClose: forget, returnFocus: input });
    } catch (_) {
      panes = null;
    }
  }
  function titleFor(node) {
    const lang = node.querySelector('.allen-lang');
    const name = lang ? lang.textContent.trim().toLowerCase() : '';
    if (name === 'omega' || name === 'om') return 'Omega program';
    if (name === 'html' || name === 'htm') return 'App';
    if (node.matches('.allen-consent')) return 'Remember me';
    if (node.matches('.allen-code')) return name ? `Code (${name})` : 'Code';
    const head = node.querySelector('h3, h4, strong, p');
    const text = head ? head.textContent.trim() : '';
    return text ? text.slice(0, 60) : 'Aien';
  }
  function paneFor(node, item) {
    if (!panes) return;
    const opened = panes.openNode({ node, id: freshId('c'), title: titleFor(node), focus: false });
    if (opened && opened.ok) keep({ id: opened.id, close: opened.close, item });
  }
  function paneEvents(events) {
    const ids = new Map();
    for (const one of events) {
      if (!one || typeof one.event !== 'string' || !one.data || typeof one.data !== 'object') continue;
      const data = { ...one.data };
      if (typeof data.id === 'string') {
        if (!ids.has(data.id)) ids.set(data.id, freshId('m'));
        data.id = ids.get(data.id);
      }
      const done = panes.event(one.event, data);
      if (one.event === 'pane.open' && done && done.ok) {
        const id = done.id;
        keep({ id, close: () => panes.event('pane.close', { v: data.v, id }) });
      }
    }
  }
  async function compute(expression, out) {
    const said = text => {
      if (out) out.textContent = text;
    };
    if (!panes) return said('Glass panes need a newer browser.');
    said('Computing with the Omega math engine...');
    let reply = null;
    let response = null;
    try {
      response = await fetch(MATH, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({ expression, title: expression.slice(0, 200) }),
        cache: 'no-store',
        credentials: 'omit'
      });
      reply = await response.json();
    } catch (_) {
      return said('The math engine did not answer. Try again in a minute.');
    }
    if (!response.ok || !reply || !Array.isArray(reply.events)) {
      const why = reply && typeof reply.message === 'string' ? reply.message.slice(0, 300) : `The math engine answered ${response.status}.`;
      return said(why);
    }
    paneEvents(reply.events);
    said(typeof reply.result === 'string' ? reply.result.slice(0, 600) : '');
  }
  let mathId = '';
  function openMath(first) {
    if (!panes) return;
    if (mathId && mine.some(entry => entry.id === mathId)) {
      const field = panesHost.querySelector('.aien-mathform input');
      if (first && field) {
        field.value = first;
        compute(first, panesHost.querySelector('.aien-mathform output'));
      }
      if (field) field.focus();
      return;
    }
    const box = document.createElement('form');
    box.className = 'aien-mathform';
    const label = document.createElement('label');
    label.textContent = 'An expression for the Omega math engine';
    const field = document.createElement('input');
    field.type = 'text';
    field.maxLength = 4096;
    field.autocomplete = 'off';
    field.spellcheck = false;
    field.placeholder = 'Integrate[x^2, {x, 0, 1}]';
    label.append(field);
    const go = document.createElement('button');
    go.type = 'submit';
    go.textContent = 'Compute';
    const out = document.createElement('output');
    const note = document.createElement('p');
    note.className = 'aien-note';
    note.textContent = 'Exact algebra, calculus and numbers, computed on my Spark by Aien\'s Omega math engine. Each result opens its own pane with its provenance.';
    box.append(label, go, out, note);
    box.addEventListener('submit', event => {
      event.preventDefault();
      const expression = field.value.trim();
      if (expression) compute(expression, out);
    });
    const opened = panes.openNode({ node: box, id: freshId('math'), title: 'Math', focus: false });
    if (!opened || !opened.ok) return;
    mathId = opened.id;
    keep({ id: opened.id, close: opened.close });
    if (first) {
      field.value = first;
      compute(first, out);
    }
    field.focus();
  }
  /* The speed test is InferLab's AienSpeed component when the page has it;
     until then the pane holds the live table allen.js fills from the stream
     of each reply, with one button that asks Aien something to time. */
  let speedId = '';
  function openSpeed() {
    if (!panes) return;
    if (speedId) return;
    const box = document.createElement('div');
    box.className = 'aien-speedpane';
    let mounted = false;
    if (window.AienSpeed && typeof window.AienSpeed.mount === 'function') {
      try {
        window.AienSpeed.mount(box, {});
        mounted = true;
      } catch (_) {
        box.replaceChildren();
      }
    }
    if (!mounted) {
      const note = document.createElement('p');
      note.className = 'aien-note';
      note.textContent = 'Measured by this page from the live stream of Aien\'s latest reply, on the live model on my DGX Spark.';
      const go = document.createElement('button');
      go.type = 'button';
      go.className = 'aien-tool';
      go.textContent = 'Time a reply now';
      go.addEventListener('click', () => {
        if (window.allen && root.dataset.busy !== 'true') window.allen.send('In about 120 words, tell me how two black holes merge.');
      });
      box.append(speedTable, note, go);
    }
    const opened = panes.openNode({ node: box, id: freshId('speed'), title: 'Speed test', focus: false });
    if (!opened || !opened.ok) {
      speedHome.before(speedTable);
      return;
    }
    speedId = opened.id;
    keep({ id: opened.id, close: opened.close });
  }
  /* Commands typed into the oval: /math <expression> and /speed open panes
     instead of going to the model. Capture runs before allen.js's own submit. */
  form.addEventListener('submit', event => {
    const text = input.value.trim();
    const math = /^\/math\s+([\s\S]+)$/i.exec(text);
    const speed = /^\/speed\s*$/i.test(text);
    if (!math && !speed) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    sceneCall('key', text);
    input.value = '';
    grow();
    if (math) openMath(math[1].trim());
    else openSpeed();
  }, true);
  function grow() {
    input.style.height = 'auto';
    input.style.height = `${Math.min(input.scrollHeight, 132)}px`;
  }
  input.addEventListener('input', grow);
  /* Typing anywhere on the page types to Aien, as on the iMac. */
  document.addEventListener('keydown', event => {
    if (event.defaultPrevented || event.ctrlKey || event.metaKey || event.altKey) return;
    const target = event.target;
    if (target !== document.body && target !== document.documentElement && target !== sky) return;
    if (event.key.length === 1) input.focus({ preventScroll: true });
  });
  function wire() {
    const chat = window.allen;
    if (!chat || typeof chat.on !== 'function') return;
    chat.on('send', detail => {
      root.dataset.spoke = 'yes';
      held = false;
      hideBubble(false);
      if (!detail.silent) sceneCall('key', detail.text);
      sceneCall('mode', 'thinking');
    });
    chat.on('start', () => sceneCall('mode', 'thinking'));
    chat.on('token', detail => {
      sceneCall('speak', detail.text);
      soon();
    });
    chat.on('human', detail => sceneCall('speak', detail.text));
    const settle = () => {
      sceneCall('mode', 'idle');
      soon();
      requestAnimationFrame(schedule);
    };
    chat.on('reply', settle);
    chat.on('done', settle);
    chat.on('error', settle);
  }
  function start() {
    startScene();
    startPanes();
    showSound();
    new MutationObserver(soon).observe(log, { childList: true, subtree: true, characterData: true });
    for (const kind of ['pointerdown', 'keydown']) document.addEventListener(kind, firstGesture, { capture: true, passive: true });
    bubble.addEventListener('pointerenter', event => {
      if (event.pointerType === 'touch') return;
      held = true;
      clearTimers();
      bubble.dataset.state = 'shown';
    });
    bubble.addEventListener('pointerleave', event => {
      if (event.pointerType === 'touch') return;
      held = bubble.contains(document.activeElement);
      schedule();
    });
    bubble.addEventListener('focusin', () => {
      held = true;
      clearTimers();
      bubble.dataset.state = 'shown';
    });
    bubble.addEventListener('focusout', () => {
      held = false;
      schedule();
    });
    /* A tap holds the bubble on touch screens; a second tap lets it go. */
    bubble.addEventListener('click', event => {
      if (event.target.closest('button, a')) return;
      held = !held;
      if (held) {
        clearTimers();
        bubble.dataset.state = 'shown';
      } else schedule();
    });
    /* Escape lets the bubble go at once, unless a pane took the key. */
    document.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || event.defaultPrevented || bubble.hidden) return;
      held = false;
      hideBubble(false);
    });
    replayButton.addEventListener('click', replay);
    soundButton.addEventListener('click', () => {
      if (!audio) return;
      audio.setMuted(!audio.muted());
      showSound();
    });
    speedButton.addEventListener('click', openSpeed);
    mathButton.addEventListener('click', () => openMath(''));
    if (/^#r=/.test(location.hash)) openSpeed();
    if (window.allen) wire();
    else document.addEventListener('allen-ready', wire, { once: true });
    soon();
    root.dataset.universe = 'on';
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true });
  else start();
})();
